insert into checklists (title, description, groups, sort_order) values ('New Tenant', 'From approved application through to move-in day.', '[{"name":"Application approved","steps":[{"text":"Confirm in writing that application has been approved and accepted by both parties","evidence":"screenshot"},{"text":"Enter tenant(s) contact details into Palace and attach to relevant property","evidence":"screenshot"},{"text":"Enter tenancy dates and term of agreement into Palace","evidence":"screenshot"},{"text":"Enter rent review date into Palace","evidence":"screenshot"},{"text":"Check rental amount and confirm weekly or fortnightly payments","evidence":"tick"},{"text":"Enter bond amount due into Palace","evidence":"screenshot"},{"text":"Confirm letting fee is the correct amount to be charged to the landlord","evidence":"tick"},{"text":"Confirm rental amount in tenant matches the property and adjust if required","evidence":"tick"},{"text":"Note any special conditions in tenant file","evidence":"screenshot"},{"text":"Confirm details of Body Corporate (if applicable)","evidence":"tick"},{"text":"Confirm if pets are approved (if applicable)","evidence":"tick"},{"text":"Confirm amount tenant is to be charged for water (if applicable)","evidence":"tick"},{"text":"Enter ingoing water meter reading on tenant profile in Palace","evidence":"screenshot"},{"text":"Confirm arrangements for gardens and lawn maintenance (if applicable)","evidence":"tick"},{"text":"Confirm arrangements for pool maintenance (if applicable)","evidence":"tick"},{"text":"Confirm all details for this tenancy have been entered into Palace","evidence":"tick"},{"text":"Prepare tenancy agreement and pack (agreement x3, arrears policy, maintenance policy, key release form, bond lodgement form, welcome pack)","evidence":"screenshot"},{"text":"Schedule ingoing Property Condition Report","evidence":"screenshot"},{"text":"Schedule inventory (if applicable)","evidence":"tick"},{"text":"Prepare Fastconnect or Movinghub form (if applicable)","evidence":"tick"},{"text":"File all relevant information and documents in tenant file","evidence":"screenshot"}]},{"name":"On the day the tenancy agreement is signed","steps":[{"text":"Verify with tenant that details on the agreement are correct (move-in date, bond, rent & frequency, pets, smoking, occupants)","evidence":"tick"},{"text":"Explain tenancy agreement in full to the tenant(s)","evidence":"tick"},{"text":"Explain agency policies","evidence":"tick"},{"text":"All parties to sign bond lodgement form","evidence":"screenshot"},{"text":"Tenant to pay full ingoing costs at point of signing","evidence":"tick"},{"text":"Tenant(s) to sign utility connection form (if applicable)","evidence":"tick"},{"text":"Advise tenant(s) to organise contents insurance","evidence":"tick"},{"text":"Advise tenant(s) regarding maintenance and care of smoke detectors","evidence":"tick"},{"text":"Advise tenant(s) on pool / garden care where applicable","evidence":"tick"},{"text":"Photocopy tenancy agreement and give a copy to tenant(s)","evidence":"tick"},{"text":"File original tenancy agreement","evidence":"screenshot"},{"text":"Arrange for the For Rent sign to be removed","evidence":"tick"},{"text":"Remove property from websites","evidence":"screenshot"},{"text":"Cancel any pre-booked advertising / marketing","evidence":"tick"},{"text":"Send utility connection form (if applicable)","evidence":"tick"}]},{"name":"Prior to move-in date","steps":[{"text":"Check ingoing Property Condition Report has been completed","evidence":"screenshot"},{"text":"Print three copies of ingoing Property Condition Report","evidence":"tick"},{"text":"Check welcome and information pack is ready for move-in","evidence":"tick"},{"text":"Arrange a time for tenant(s) to collect keys","evidence":"tick"}]},{"name":"Move-in date","steps":[{"text":"Check initial rent and bond has been paid in full and receipted","evidence":"screenshot"},{"text":"Check all documentation is ready for key release","evidence":"tick"},{"text":"Ensure tenant(s) sign office copy of key release","evidence":"screenshot"},{"text":"Ensure tenant(s) sign office copy of ingoing Property Condition Report","evidence":"screenshot"},{"text":"Ensure tenant(s) sign office copy of inventory (if applicable)","evidence":"tick"},{"text":"Explain welcome and information pack","evidence":"tick"}]}]'::jsonb, 0);
insert into checklists (title, description, groups, sort_order) values ('Vacating Tenant', 'Notice through to bond refund and filing.', '[{"name":"On receipt of notice","steps":[{"text":"Confirm when written notice has been received / issued from/to the tenants","evidence":"screenshot"},{"text":"Confirm the correct notice period has been received/issued","evidence":"tick"},{"text":"Confirm tenant has periodic or expiring fixed term and is not breaking tenancy","evidence":"tick"},{"text":"Enter vacate date in Palace","evidence":"screenshot"},{"text":"Enter tenant forwarding address and new contact numbers in Palace","evidence":"screenshot"},{"text":"Contact owner to advise of vacate notice and discuss rent review","evidence":"tick"},{"text":"If rent is to increase, update in Palace and increase bond and letting fee","evidence":"screenshot"},{"text":"Forward email to owner confirming vacate date, rental amount and advertising details","evidence":"screenshot"},{"text":"Forward letter of confirmation to tenant(s) with vacate procedures, cleaning guide and ingoing PCR","evidence":"screenshot"},{"text":"Schedule date for final bond inspection in Palace","evidence":"screenshot"},{"text":"Arrange for For Rent sign to be erected","evidence":"tick"},{"text":"Upload property onto appropriate websites","evidence":"screenshot"},{"text":"Arrange and book other advertising / marketing as per agreed schedule","evidence":"tick"},{"text":"Place tenant file in vacate rack","evidence":"screenshot"}]},{"name":"On day of vacate","steps":[{"text":"Confirm rent is paid to vacate date","evidence":"screenshot"},{"text":"Read water meter (if applicable) and invoice tenant(s)","evidence":"screenshot"},{"text":"Take photographs to verify condition of property","evidence":"screenshot"},{"text":"Confirm property condition is acceptable compared to ingoing PCR","evidence":"tick"},{"text":"If not, arrange extra cleaning or necessary maintenance and repairs","evidence":"tick"},{"text":"Schedule re-inspection","evidence":"screenshot"}]},{"name":"Finalising","steps":[{"text":"Schedule date for return of invoices for extra work to be charged to tenant(s)","evidence":"tick"},{"text":"Check returned keys against keys given at start of tenancy","evidence":"tick"},{"text":"Photocopy and file receipts (carpet cleaning, pest control, professional cleaning, pool certificate as applicable)","evidence":"screenshot"},{"text":"Photocopy and give tenant(s) copy of Exit Condition Report (retain original)","evidence":"screenshot"},{"text":"File final bond inspection report and any extra work scheduled plus invoices","evidence":"screenshot"},{"text":"File vacating tenant checklist","evidence":"screenshot"},{"text":"Check with owner prior to finalising the bond","evidence":"tick"},{"text":"Follow bond refund process","evidence":"screenshot"}]}]'::jsonb, 1);
insert into checklists (title, description, groups, sort_order) values ('Rent Review', 'Rent review report through to bond top-up.', '[{"name":"Preparing the review","steps":[{"text":"Prepare and print rent review report two months in advance of review date","evidence":"screenshot"},{"text":"Check tenant(s) for any special rent review clauses","evidence":"tick"},{"text":"Prepare CMA (Comparative Market Analysis) to substantiate rental rate advice","evidence":"screenshot"},{"text":"Forward email to owner with CMA to advise if rent could increase or remain, and request authorisation","evidence":"screenshot"}]},{"name":"Rental increase and renewal accepted","steps":[{"text":"Enter details of rent increase in Palace","evidence":"screenshot"},{"text":"Issue tenant(s) with minimum 60 days notice of rent increase (plus service days)","evidence":"screenshot"},{"text":"Advise tenant(s) of additional funds required to increase bond accordingly","evidence":"tick"},{"text":"Send bond increase amount to MBIE","evidence":"screenshot"}]}]'::jsonb, 2);
insert into checklists (title, description, groups, sort_order) values ('New Management - Existing Tenant', 'Taking on a property that already has a tenant.', '[{"name":"Setup","steps":[{"text":"Ensure Management Authority is completed and signed by all required parties","evidence":"screenshot"},{"text":"Give a copy of the Management Authority to the owner with welcome letter/pack","evidence":"tick"},{"text":"Create property file and file original Management Authority","evidence":"screenshot"},{"text":"Enter owner, property and tenant details into Palace","evidence":"screenshot"},{"text":"File copy of notification from owner advising current agent of transfer","evidence":"screenshot"},{"text":"Mark date in calendar for official transfer of management","evidence":"screenshot"},{"text":"Send letter to current managing agent requesting handover documents (agreement, PCR, ledger, keys, bond form, active notices, correspondence)","evidence":"screenshot"},{"text":"Notify tenant in writing of management transfer","evidence":"screenshot"},{"text":"Set schedule in Palace for recurring routine inspections (13 weekly)","evidence":"screenshot"},{"text":"Send notifications to Council / Body Corporate / Insurer for accounts (if applicable)","evidence":"tick"},{"text":"Enter insurance policy and renewal dates into Palace","evidence":"screenshot"},{"text":"Enter owner maintenance instructions and spend limit into Palace","evidence":"screenshot"}]},{"name":"On day of handover","steps":[{"text":"Ensure all documentation has been received and follow up if necessary","evidence":"tick"},{"text":"Record keys in register and Palace, tag, code, photocopy and place in cabinet","evidence":"screenshot"},{"text":"Enter tenant paid-to-date into Palace","evidence":"screenshot"},{"text":"Lodge Change of Landlord/Agent form with MBIE","evidence":"screenshot"},{"text":"Send letter to owner advising of successful transfer (owners pack, photocopy of keys received)","evidence":"screenshot"},{"text":"Send welcome pack to tenants (ledger, keys held, ingoing PCR)","evidence":"screenshot"}]}]'::jsonb, 3);
insert into checklists (title, description, groups, sort_order) values ('New Management - Owner Occupied', 'Taking on a vacant owner-occupied property to market.', '[{"name":"Setup and marketing","steps":[{"text":"Ensure Management Authority is completed and signed by ALL required parties","evidence":"screenshot"},{"text":"Key release form to be signed by owner","evidence":"screenshot"},{"text":"Give a copy of the Management Authority to the owner with welcome letter/pack","evidence":"tick"},{"text":"Create property file and file original Management Authority","evidence":"screenshot"},{"text":"Confirm Landlord Protection Insurance has been offered and followed up","evidence":"tick"},{"text":"Arrange Landlord Protection Insurance (if applicable)","evidence":"tick"},{"text":"Ensure all owner and property details are accurate and enter into Palace","evidence":"screenshot"},{"text":"Record keys in register and Palace, tag, code, photocopy and place in cabinet","evidence":"screenshot"},{"text":"Enter insurance policy and renewal dates into Palace","evidence":"screenshot"},{"text":"Enter owner maintenance instructions and spend limit into Palace","evidence":"screenshot"},{"text":"Set schedule in Palace for recurring routine inspections (13 weekly)","evidence":"screenshot"},{"text":"Photograph property for advertising purposes","evidence":"screenshot"},{"text":"Arrange for For Rent sign to be erected at property","evidence":"tick"},{"text":"Arrange and book advertising and marketing as per agreed schedule","evidence":"tick"},{"text":"Load property onto applicable websites","evidence":"screenshot"},{"text":"Arrange times for property to be viewed and set up schedule","evidence":"screenshot"},{"text":"Ensure all team are aware of the new listing and viewing instructions","evidence":"tick"},{"text":"Advise prospective tenants database of new listing","evidence":"tick"},{"text":"Send notifications to Council / Body Corporate / Insurer for accounts (if applicable)","evidence":"tick"},{"text":"Schedule time for ingoing Property Condition Report to be completed","evidence":"screenshot"}]}]'::jsonb, 4);
insert into checklists (title, description, groups, sort_order) values ('New Management - Vacant Property', 'Taking on a vacant property to market for lease.', '[{"name":"Setup and marketing","steps":[{"text":"Ensure Management Authority is completed and signed by ALL required parties","evidence":"screenshot"},{"text":"Key release form to be signed by owner","evidence":"screenshot"},{"text":"Give a copy of the Management Authority to the owner with welcome letter/pack","evidence":"tick"},{"text":"Create property file and file original Management Authority","evidence":"screenshot"},{"text":"Confirm Landlord Protection Insurance has been offered and followed up","evidence":"tick"},{"text":"Arrange Landlord Protection Insurance (if applicable)","evidence":"tick"},{"text":"Ensure all owner and property details are accurate and enter into Palace","evidence":"screenshot"},{"text":"Record keys in register and Palace, tag, code, photocopy and place in cabinet","evidence":"screenshot"},{"text":"Enter insurance policy and renewal dates into Palace","evidence":"screenshot"},{"text":"Enter owner maintenance instructions and spend limit into Palace","evidence":"screenshot"},{"text":"Set schedule in Palace for recurring routine inspections (13 weekly)","evidence":"screenshot"},{"text":"Arrange repairs, maintenance, gardening and/or cleaning if necessary","evidence":"tick"},{"text":"Photograph property for advertising purposes","evidence":"screenshot"},{"text":"Arrange for For Rent sign to be erected at property","evidence":"tick"},{"text":"Arrange and book advertising and marketing as per agreed schedule","evidence":"tick"},{"text":"Load property onto applicable websites","evidence":"screenshot"},{"text":"Arrange times for property to be viewed and set up schedule","evidence":"screenshot"},{"text":"Ensure all team are aware of the new listing and viewing instructions","evidence":"tick"},{"text":"Advise prospective tenants database of new listing","evidence":"tick"},{"text":"Send notifications to Council / Body Corporate / Insurer for accounts (if applicable)","evidence":"tick"},{"text":"Send notification to Water Care / Veolia","evidence":"tick"}]}]'::jsonb, 5);
insert into checklists (title, description, groups, sort_order) values ('Management Listed for Sale', 'When a managed property is put on the market.', '[{"name":"On listing","steps":[{"text":"Ensure notice from listing agent / owner advising property listed for sale is received in writing","evidence":"screenshot"},{"text":"Tenant(s) issued with letter notifying them of the landlord intention to sell","evidence":"screenshot"},{"text":"Give listing agent required info (info sheet, notification, viewing schedule, tenant contacts, rent, fixed term dates, tenant letter)","evidence":"tick"},{"text":"Collect and retain a copy of the viewing schedule signed by all parties","evidence":"screenshot"}]},{"name":"Periodic tenancy - vacant possession required","steps":[{"text":"Check with sales consultant if a 42 day notice needs to be issued","evidence":"tick"},{"text":"Record date in Palace when the 42 day notice was issued (at least one day prior to settlement)","evidence":"screenshot"},{"text":"Set reminder date to follow up with tenant(s) to ensure vacating on correct date","evidence":"screenshot"},{"text":"Schedule final bond inspection","evidence":"screenshot"}]},{"name":"Tenancy to remain in place","steps":[{"text":"If purchased by investor and tenant continuing, contact purchaser to co-ordinate management","evidence":"tick"},{"text":"If management continuing with agency, forward a letter to the tenant(s) confirming no changes","evidence":"screenshot"}]},{"name":"Prior to / on settlement (investment purchase)","steps":[{"text":"Schedule date in Palace as reminder of settlement day","evidence":"screenshot"},{"text":"Run Change of Ownership wizard in Palace (if applicable)","evidence":"screenshot"},{"text":"Ensure rental payments are credited to appropriate owner","evidence":"screenshot"},{"text":"Ensure property card and tenant have been linked to the new owner in Palace","evidence":"screenshot"},{"text":"Check if final water meter reading is required","evidence":"tick"},{"text":"Check all invoices are paid or flag any outstanding","evidence":"tick"}]}]'::jsonb, 6);
insert into checklists (title, description, groups, sort_order) values ('Finalisation of Management', 'Handover of a management to a new agency or owner.', '[{"name":"On cancellation","steps":[{"text":"Written advice of cancellation received from owner / or sent by agency","evidence":"screenshot"},{"text":"Put owner funds on hold and check for any outstanding invoices","evidence":"screenshot"},{"text":"Confirm required notice received / given","evidence":"tick"},{"text":"Handover date entered into Palace","evidence":"screenshot"},{"text":"Confirm notification received and send letter to owner (if applicable)","evidence":"tick"},{"text":"Prepare copies (if remaining tenanted): agreement, PCR, ledger, paid-to date, keys given to tenant","evidence":"screenshot"},{"text":"Prepare copies of any outstanding tenant invoices","evidence":"tick"},{"text":"Prepare bond transfer (Change of Landlord/Agent form)","evidence":"screenshot"},{"text":"If tenant vacating, owner to check property prior to bond release and sign off condition","evidence":"tick"},{"text":"Photocopy all management keys / remotes retained in office","evidence":"screenshot"},{"text":"Ensure enough funds held in trust to pay accounts and management fees","evidence":"screenshot"},{"text":"Send notification to tenant(s) advising management end and last payment due","evidence":"screenshot"}]},{"name":"On day of finalisation","steps":[{"text":"Check maintenance pending and process all accounts","evidence":"screenshot"},{"text":"Confirm all management, sundry, letting fees have been deducted","evidence":"tick"},{"text":"Send notification to Council / Body Corporate / Insurance of change of management","evidence":"tick"},{"text":"Handover prepared documents and keys to owner and/or new agent","evidence":"tick"},{"text":"Ensure new agent / owner signs confirmation of receipt of keys and documents","evidence":"screenshot"},{"text":"Send email to owner confirming transfer / handover","evidence":"screenshot"}]},{"name":"End of month","steps":[{"text":"On completion of end of month, mark owner, tenant and property as inactive in Palace","evidence":"screenshot"},{"text":"Archive owner / tenant and property with reason for lost management stated","evidence":"screenshot"}]}]'::jsonb, 7);
